# =========================
def product_status(product):
    return str(
        get_row_value(
            product,
            "Stock status", "Stock Status", "StockStatus", "stock_status",
            "Availability", "availability", "Status", "status",
            "ပစ္စည်းအခြေအနေ", "လက်ကျန်အခြေအနေ",
        )
        or ""
    ).strip().lower()


def product_availability(product):
    """Normalize Sheet stock wording into in_stock / coming / out / unknown."""
    raw = product_status(product)
    compact = re.sub(r"[\s_\-]+", " ", raw).strip()
    joined = re.sub(r"[^a-z0-9က-အ]+", "", compact)

    # Check unavailable states BEFORE any positive word such as "stock" / "ရှိ".
    out_words = (
        "out of stock", "outofstock", "sold out", "soldout", "no stock",
        "nostock", "unavailable", "ကုန်နေ", "ပစ္စည်းကုန်", "ကုန်ပြီ",
        "လက်ကျန်မရှိ", "stock out", "stockout",
    )
    coming_words = (
        "coming soon", "comingsoon", "coming", "not arrived", "notarrived",
        "not arrive", "not yet arrived", "on the way", "ontheway",
        "preorder", "pre order", "မရောက်သေး", "ပစ္စည်းမရောက်သေး",
        "လမ်းမှာ", "လမ်းတွင်", "ကြိုတင်မှာ", "မှာထားဆဲ",
    )
    in_words = (
        "in stock", "instock", "available", "ready stock", "readystock",
        "ready", "လက်ကျန်ရှိ", "ပစ္စည်းရှိ", "ရှိပါတယ်", "ရှိ",
    )

    def hit(words):
        return any(w in compact or re.sub(r"[^a-z0-9က-အ]+", "", w) in joined for w in words)

    if compact in ("out", "ကုန်", "ကုန်ပြီ"):
        return "out"
    if compact in ("coming", "coming soon", "မရောက်သေး"):
        return "coming"
    if compact in ("in stock", "instock", "ရှိ", "available"):
        return "in_stock"

    if hit(out_words):
        return "out"
    if hit(coming_words):
        return "coming"
    if hit(in_words):
        return "in_stock"

    # Preserve compatibility with existing rows that predate the Stock Status column.
    if not compact:
        return "in_stock"
    return "unknown"


def product_is_sellable(product):
    return product_availability(product) == "in_stock"


_MH_PRICE_OR_FEE = re.compile(
    r"ဈေး|စျေး|ပို့ခ|ပို့ဆောင်ခ|ပို့ဆောင်စရိတ်|ရန်ကုန်ပို့|နယ်ပို့|အပြီးအစီး|"
    r"\b(?:price|shipping|deli)\b|delivery\s*(?:fee|charge|cost)|"
    r"\d[\d,. ]*\s*(?:ks\b|mmk\b|ကျပ်)|"
    r"\d{1,3}(?:[,， ]\d{3})+|(?<!\d)\d{5,}(?!\d)|"
    r"(?:တစ်|နှစ်|သုံး|လေး|ငါး|ခြောက်|ခုနစ်|ရှစ်|ကိုး|ဆယ်|[\d])"
    r"\s*(?:ထောင်|သောင်း|သိန်း|သန်း)", re.I
)

_MH_PRICE_CONFIRMATION = re.compile(
    r"(?:(?:ထောင်|သောင်း|သိန်း|သန်း)(?:ခွဲ)?\s*(?:လား|လဲ|ဟုတ်)|"
    r"(?:[\d,，]{4,}|\d\s*(?:k|ထောင်|သောင်း|သိန်း))"
    r"\s*(?:ks|mmk|ကျပ်)?\s*(?:လား|လဲ|ဟုတ်|နော်|[?？]|$))", re.I
)


def _mingalar_safe_product_detail(value):
    """Remove stale price/shipping copy from catalog descriptions for Mingalar.

    Mingalar's customer price is calculated in product_reply() as one all-in
    amount. Some legacy Sheet descriptions also contain Snow-style base-price
    and delivery-fee copy, which must not be sent to Mingalar customers.
    """
    text = str(value or "").strip()
    if not text:
        return ""

    # Treat each explicit line as a unit. If old pricing is embedded in the
    # same line as a description, omit that line rather than risk sending a
    # contradictory price to a customer.
    parts = re.split(r"\n+|[;；]", text)
    safe_parts = []
    for part in parts:
        part = part.strip(" \t\r\n•·-")
        if part and not _MH_PRICE_OR_FEE.search(part):
            safe_parts.append(part)
    return "\n".join(safe_parts).strip()


def product_detail(product, page_name=""):
    detail = str(
        get_row_value(
            product,
            "Description",
            "Detail",
            "Details",
            "Product Detail",
            "Product Details",
            "Description Myanmar",
            "Myanmar Description",
            "အသေးစိတ်",
        )
        or ""
    ).strip()
    if is_mingalar_page(page_name):
        return _mingalar_safe_product_detail(detail)
    return detail



def normalize_page_name(value):
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def is_mingalar_page(value):
    return normalize_page_name(value) in {
        normalize_page_name(MINGALAR_PAGE_NAME), "mh", "mingalar",
        "mingalar happy", "mingalar happy shopping",
    }


def manychat_page_name(data):
    # Explicit page identity wins; an omitted field must not erase a known MH
    # session. The dedicated endpoint also identifies first-time MH customers.
    if request.path.rstrip("/") == "/webhook/mh":
        return MINGALAR_PAGE_NAME
    for key in ("page", "page_name", "shop_page_name"):
        value = str(data.get(key, "") or "").strip()
        if value:
            if is_mingalar_page(value):
                return MINGALAR_PAGE_NAME
            if normalize_page_name(value) in {"sn", "sp", "snow phyu", "snow phyu online shopping"}:
                return ""
    contact_id = str(data.get("contact_id", "") or "").strip()
    return session_page_name(ORDER_SESSIONS.get(contact_id, {}))


def session_page_name(session):
    if isinstance(session, dict) and is_mingalar_page(session.get("_page_name", "")):
        return MINGALAR_PAGE_NAME
    return ""


def telegram_credentials_for_page(page_name=""):
    if is_mingalar_page(page_name):
        return MINGALAR_TELEGRAM_BOT_TOKEN, MINGALAR_TELEGRAM_CHAT_ID
    return TELEGRAM_BOT_TOKEN, TELEGRAM_CHAT_ID


def product_reply(code, product, page_name=""):
    name = str(get_row_value(product, "Product Name", "Name")).strip()

    price = product_price_from_row(product, page_name)

    yangon_delivery = parse_int_amount(
        get_row_value(product, "Yangon Delivery", "YangonDelivery"),
        DEFAULT_YANGON_DELIVERY,
    )

    other_delivery = parse_int_amount(
        get_row_value(product, "Other City Delivery", "Other Delivery", "OtherCityDelivery"),
        DEFAULT_OTHER_DELIVERY,
    )

    if not yangon_delivery:
        yangon_delivery = DEFAULT_YANGON_DELIVERY

    if not other_delivery:
        other_delivery = DEFAULT_OTHER_DELIVERY

    availability = product_availability(product)

    if availability == "out":
        return f"Code {code} {name}\nလက်ရှိ ပစ္စည်းကုန်နေပါတယ်ရှင်။"

    if availability == "coming":
        return f"Code {code} {name}\nလက်ရှိ ပစ္စည်းမရောက်သေးပါရှင်။"

    if availability == "unknown":
        return f"Code {code} {name}\nပစ္စည်းအခြေအနေကို Admin က စစ်ဆေးပေးပါမယ်ရှင်။"

    # V58 Page 2 rule: show exactly one customer-facing all-in price.
    # Snow Phyu keeps its original Yangon/Other delivery display unchanged.
    if is_mingalar_page(page_name):
        if price <= 0:
            return unavailable_order_reply(code, "price_missing")
        return (
            f"Code {code} {name}\n\n"
            f"အိမ်အရောက် အပြီးအစီး - {price:,} Ks\n\n"
            "ပစ္စည်းရောက်မှ ငွေချေ (COD) ရပါတယ်ရှင်။"
        )

    yangon_total = price + yangon_delivery
    other_total = price + other_delivery

    return (
        f"Code {code} {name}\n\n"
        f"ဈေးနှုန်း - {price:,} Ks\n\n"
        f"ရန်ကုန်ပို့ခ - {yangon_delivery:,} Ks\n"
        f"ရန်ကုန် စုစုပေါင်း - {yangon_total:,} Ks\n\n"
        f"နယ်ပို့ခ - {other_delivery:,} Ks\n"
        f"နယ် စုစုပေါင်း - {other_total:,} Ks\n\n"
        "ပစ္စည်းရောက်မှ ငွေချေ (COD) ရပါတယ်ရှင်။"
    )


