# ROUTES
# =========================
# Warm the Sheet outside customer-request latency and keep it fresh continuously.
# If this first background attempt is still running, a true cold request can still
# perform the bounded first load (4s max) via load_products().
threading.Thread(target=load_products, kwargs={"force": True}, daemon=True).start()
start_catalog_refresh_loop()

@app.route("/", methods=["GET"])
def home():
    return f"Facebook AI Bot is running! {BOT_VERSION}", 200


@app.route("/webhook", methods=["GET"])
def verify_webhook():
    mode = request.args.get("hub.mode")
    token = request.args.get("hub.verify_token")
    challenge = request.args.get("hub.challenge")

    if mode == "subscribe" and token == VERIFY_TOKEN:
        return challenge, 200

    return "Verification failed", 403




# V60: validated image-byte cache for ManyChat/Messenger delivery.
_PRODUCT_IMAGE_PROXY_CACHE = {}
_PRODUCT_IMAGE_PROXY_LOCK = threading.Lock()

def _download_valid_product_image(source_url):
    """Fetch actual image bytes; never disguise a Google/HTML page as image/jpeg."""
    source_url = str(source_url or "").strip()
    if not source_url:
        return None, None

    cache_key = hashlib.sha1(source_url.encode("utf-8", errors="ignore")).hexdigest()
    with _PRODUCT_IMAGE_PROXY_LOCK:
        cached = _PRODUCT_IMAGE_PROXY_CACHE.get(cache_key)
    if cached:
        return cached

    candidates = []
    file_id = google_drive_file_id(source_url)
    if file_id:
        candidates.extend([
            f"https://lh3.googleusercontent.com/d/{file_id}",
            f"https://drive.google.com/uc?export=download&id={file_id}",
        ])
    candidates.append(source_url)

    seen = set()
    for candidate in candidates:
        if not candidate or candidate in seen:
            continue
        seen.add(candidate)
        try:
            r = requests.get(
                candidate,
                timeout=12,
                allow_redirects=True,
                headers={"User-Agent": "Mozilla/5.0"},
            )
            r.raise_for_status()
            raw = r.content or b""
            header = r.headers.get("Content-Type", "")
            mime = _image_mime_from_bytes(raw, header)
            if not raw or not mime or not mime.startswith("image/"):
                print("V60 IMAGE SOURCE REJECTED (NOT REAL IMAGE):", candidate, header, len(raw), flush=True)
                continue
            value = (raw, mime)
            with _PRODUCT_IMAGE_PROXY_LOCK:
                if len(_PRODUCT_IMAGE_PROXY_CACHE) > 100:
                    _PRODUCT_IMAGE_PROXY_CACHE.clear()
                _PRODUCT_IMAGE_PROXY_CACHE[cache_key] = value
            print("V60 IMAGE SOURCE OK:", mime, len(raw), candidate, flush=True)
            return value
        except Exception as e:
            print("V60 IMAGE SOURCE ERROR:", candidate, str(e), flush=True)

    return None, None

@app.route("/product-image/<code>.jpg", methods=["GET"])
@app.route("/product-image/<code>", methods=["GET"])
def product_image_proxy(code):
    """Serve the current Google-Sheet product image from the same public app.

    The route is code-driven, so changing the Sheet image never requires Python
    edits.  A short browser/CDN cache is safe because the ManyChat URL includes a
    source-URL fingerprint that changes automatically with the Sheet value.
    """
    load_products(force=False)
    code = normalize_code(code)
    product = PRODUCTS.get(code)
    if not product:
        return "Not found", 404

    source_url = product_image_url(product)
    image_bytes, content_type = _download_valid_product_image(source_url)
    if not image_bytes:
        return "Image unavailable", 404

    response = Response(image_bytes, status=200, content_type=content_type or "image/jpeg")
    response.headers["Cache-Control"] = "public, max-age=300"
    response.headers["Content-Disposition"] = f'inline; filename="{code}.jpg"'
    response.headers["Content-Length"] = str(len(image_bytes))
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


@app.route("/webhook/mh", methods=["POST"])
@app.route("/webhook", methods=["POST"])
def webhook():
    data = request.get_json(silent=True)

    print("=== WEBHOOK POST RECEIVED ===", flush=True)
    if isinstance(data, dict):
        body_voucher_key = str(data.pop("voucher_key", "") or "")
        g.voucher_key = request.headers.get("X-Voucher-Key", "") or body_voucher_key
    print(data, flush=True)

    # V50 dual-path Admin takeover. Meta message_echoes remains the primary path;
    # an explicit ManyChat/external-request signal is a safe fallback when Meta does
    # not deliver the outgoing echo. This check MUST happen before buyer processing.
    if isinstance(data, dict) and is_explicit_admin_takeover_payload(data):
        return handle_explicit_admin_takeover(data), 200

    # ManyChat Dynamic Block request.
    if isinstance(data, dict) and "message" in data and "contact_id" in data:
        return handle_manychat_request(data), 200

    # Unknown non-Meta request.
    if not data or data.get("object") != "page":
        return manychat_text("EVENT_RECEIVED"), 200

    refresh_catalog_for_customer_request("META")

    for entry in data.get("entry", []):
        for event in entry.get("messaging", []):
            message_data = event.get("message", {})
            referral = event.get("referral") or (message_data.get("referral") if isinstance(message_data, dict) else None)

            # messaging_referrals may arrive without a message object. Capture it
            # before the normal message-only flow so AD attribution is not discarded.
            if isinstance(referral, dict):
                referral_sender = str(event.get("sender", {}).get("id", "") or "").strip()
                if referral_sender:
                    remember_meta_ad_context(referral_sender, referral)

            if not message_data:
                continue

            # Page/Admin/Bot outgoing messages.
            if message_data.get("is_echo"):
                handle_echo_message(event, message_data)
                continue

            if is_duplicate_message(message_data):
                continue

            sender_id = str(
                event.get("sender", {}).get("id", "")
            ).strip()

            if not sender_id:
                continue

            text = str(message_data.get("text", "") or "").strip()
            attachments = message_data.get("attachments", []) or []

            incoming_image_urls = []
            for attachment in attachments:
                if attachment.get("type") == "image":
                    url = str(attachment.get("payload", {}).get("url", "") or "").strip()
                    if url and url not in incoming_image_urls:
                        incoming_image_urls.append(url)
            incoming_image_url = incoming_image_urls[-1] if incoming_image_urls else ""

            # V41 stores the Meta side before correlation. If ManyChat arrives later,
            # its current message can still bind Contact ID <-> PSID and inherit OFF.
            remember_meta_inbound(sender_id, text, incoming_image_url)

            # Keep all Meta-delivered sibling photos so the ManyChat Dynamic Block
            # can recover them even when Last Text Input exposes only the newest URL.
            remember_customer_images(sender_id, incoming_image_urls)

            # Correlate Meta PSID with the recent ManyChat contact for the same inbound.
            correlate_meta_sender_to_manychat(sender_id, text, incoming_image_url)
            # Correlation may have just created an alias; mirror the buffer again.
            remember_customer_images(sender_id, incoming_image_urls)

            if admin_is_active(sender_id):
                print("ADMIN ACTIVE - BOT SILENT:", sender_id, flush=True)
                continue

            if post_order_auto_stop_active(sender_id):
                print("POST-ORDER 30-MIN AUTO-STOP (META):", sender_id, text[:120], flush=True)
                continue

            if post_order_ack_active(sender_id) and is_post_order_ack(text) and not incoming_image_urls:
                print("POST-ORDER ACK IGNORED (META):", sender_id, text, flush=True)
                continue

            print("CUSTOMER:", sender_id, flush=True)
            print("TEXT:", text, flush=True)
            print("IMAGE:", incoming_image_url, flush=True)

            session = get_order_session(sender_id)

            if not incoming_image_urls:
                service = customer_service_reply(text, session)
                if service:
                    if admin_is_active(sender_id) or post_order_auto_stop_active(sender_id):
                        continue
                    reply, needs_admin = service
                    if needs_admin:
                        pause_for_admin(sender_id)
                    if reply:
                        send_facebook_text(sender_id, reply)
                    continue

            # V49 strict Sheet-first invalid-code gate for native Meta delivery.
            # Do this before stale session/order logic so 0020 cannot continue 0012.
            meta_candidates = explicit_catalog_code_candidates(text)
            meta_valid_candidates = [c for c in meta_candidates if c in PRODUCTS]
            meta_invalid_candidates = [c for c in meta_candidates if c not in PRODUCTS]
            if meta_invalid_candidates and not meta_valid_candidates:
                previous_pending = bool(session.get("_awaiting_product_clarification"))
                reset_order_context_for_unknown_product(sender_id)
                session = get_order_session(sender_id)
                session["_awaiting_product_clarification"] = previous_pending
                if unresolved_product_should_handoff(session):
                    handoff_to_admin(sender_id)
                else:
                    send_facebook_text(sender_id, "ဘယ်ပစ္စည်းလေး အလိုရှိပါလဲရှင်။")
                continue

            if meta_valid_candidates:
                clear_product_clarification(session)

            # ---------------------------------
            # 1) DIRECT CODE
            # ---------------------------------
            code, product = find_product_by_code(text)

            # ---------------------------------
            # 2) DIRECT PRODUCT NAME
            # ---------------------------------
            if not product:
                code, product = find_product_by_name(text)
            if not product:
                code, product = find_product_by_rich_sheet_text(text)

            # ---------------------------------
            # 3) CUSTOMER IMAGE / SCREENSHOT
            # ---------------------------------
            if not product and incoming_image_urls:
                meta_codes = []
                for one_image_url in incoming_image_urls:
                    for matched_code in ai_find_products_from_image(one_image_url, text):
                        if matched_code in PRODUCTS and matched_code not in meta_codes:
                            meta_codes.append(matched_code)
                if meta_codes:
                    code = meta_codes[0]
                    product = PRODUCTS.get(code)
                    for matched_code in meta_codes:
                        session["items"].setdefault(matched_code, 1)
                    session["last_product_code"] = meta_codes[-1]
                    session["quantity_confirmed"] = True

            # ---------------------------------
            # 4) DESCRIPTION / OTHER LANGUAGE
            # ---------------------------------
            if not product and text:
                code, product = ai_find_product_from_text(text)

            if product:
                clear_product_clarification(session)

            # ---------------------------------
            # EXPLICIT ADMIN REQUEST
            # ---------------------------------
            if wants_admin(text):
                handoff_to_admin(sender_id)
                continue

            if asks_delivery_time(text):
                send_facebook_text(
                    sender_id,
                    delivery_time_reply(text),
                )
                continue

            # ============================================================
            # V57 NATIVE META: SAME GLOBAL SHEET-FIRST / INFO-FIRST FRAME
            # ============================================================
            # The ManyChat path is primary, but native Meta delivery must obey
            # exactly the same rule so no route can regress multi-code/photo flow.
            meta_current_items = {}
            meta_current_codes = []

            def _v57_meta_add(raw_code, qty=1):
                code_now = normalize_code(raw_code)
                if code_now not in PRODUCTS:
                    return
                try:
                    qty_now = max(1, int(qty or 1))
                except Exception:
                    qty_now = 1
                if code_now not in meta_current_codes:
                    meta_current_codes.append(code_now)
                meta_current_items[code_now] = qty_now

            for _code, _qty in find_codes_and_quantities(text).items():
                if _code in PRODUCTS:
                    _v57_meta_add(_code, _qty)
            for _code, _qty in find_named_products_and_quantities(text).items():
                if _code in PRODUCTS:
                    _v57_meta_add(_code, _qty)

            if text:
                _rich_code, _rich_product = find_product_by_rich_sheet_text(text)
                if _rich_product and _rich_code in PRODUCTS:
                    _v57_meta_add(_rich_code, meta_current_items.get(_rich_code, 1))

            if incoming_image_urls:
                for _one_image_url in incoming_image_urls:
                    try:
                        for _matched_code in ai_find_products_from_image(_one_image_url, text):
                            if normalize_code(_matched_code) in PRODUCTS:
                                _v57_meta_add(_matched_code, 1)
                    except Exception as e:
                        print("V57 META IMAGE RECOGNITION ERROR:", str(e), flush=True)

            _meta_generic = generic_purchase_intent(text)
            if not meta_current_codes and text and (not _meta_generic or has_catalog_product_clue_text(text)):
                _ai_code, _ai_product = ai_find_product_from_text(text)
                if _ai_product and _ai_code in PRODUCTS:
                    _v57_meta_add(_ai_code, 1)

            # Stored Meta referral is a fallback only if current text/photo found none.
            if not meta_current_codes and not session.get("items") and session.get("last_product_code") not in PRODUCTS:
                _ad_code, _ad_product = restore_meta_ad_product(sender_id)
                if _ad_product and _ad_code in PRODUCTS:
                    _v57_meta_add(_ad_code, 1)

            if meta_current_codes:
                clear_product_clarification(session)
                sellable_meta = [
                    c for c in meta_current_codes
                    if product_is_sellable(PRODUCTS[c])
                ]
                if sellable_meta:
                    session["items"] = {
                        c: max(1, int(meta_current_items.get(c, 1) or 1))
                        for c in sellable_meta
                    }
                    session["last_product_code"] = sellable_meta[-1]
                    session["quantity_confirmed"] = True

                print(
                    "V57 META CURRENT PRODUCTS INFO-FIRST:",
                    meta_current_codes,
                    "ITEMS:", session.get("items", {}),
                    flush=True,
                )

                # Send every matched product once, then one order prompt total.
                for _code in meta_current_codes:
                    send_product_info_only(sender_id, _code, PRODUCTS[_code])
                if sellable_meta:
                    send_facebook_text(
                        sender_id,
                        'မှာယူလိုပါက အမည် / လိပ်စာအပြည့်အစုံ / ဖုန်းနံပါတ် ကို အပြည့်အစုံရေးပို့ပေးပါရှင်။',
                    )
                continue

            # ---------------------------------
            # PRODUCT / ORDER HANDLING
            # Keep one customer-facing text reply per incoming message.
            # Product photo + its single text reply still count as one product response.
            # ---------------------------------
            if product and is_pure_product_query(text, code, product):
                ORDER_SESSIONS[sender_id] = new_order_session()
                ORDER_SESSIONS[sender_id]["last_product_code"] = code
                send_product_response(sender_id, code, product)
                continue

            if product:
                session["last_product_code"] = code

            active_order = bool(
                session.get("items")
                or session.get("name")
                or session.get("address")
                or session.get("phone")
            )

            last_product_ready = session.get("last_product_code") in PRODUCTS

            generic_order = generic_purchase_intent(text)

            if generic_order and not product and not last_product_ready and not active_order:
                if unresolved_product_should_handoff(session):
                    handoff_to_admin(sender_id)
                else:
                    send_facebook_text(
                        sender_id,
                        "ဘယ်ပစ္စည်းလေး အလိုရှိပါလဲရှင်။",
                    )
                continue

            order_intent = (
                generic_order
                or (last_product_ready and looks_like_order_details(text))
                or (last_product_ready and looks_like_order_progress(text, session))
                or (extract_explicit_quantity(text) is not None and last_product_ready)
            )
            if order_intent or last_product_ready:
                clear_product_clarification(session)

            if active_order and not order_intent:
                print("V49 META ACTIVE ORDER + NON-ORDER TEXT - NO REPEATED PROMPT:", text, flush=True)

            if order_intent:
                if product and is_order_message(text):
                    session["items"].setdefault(code, 1)

                if not session["items"] and last_product_ready:
                    session["items"][session["last_product_code"]] = 1
                    session["quantity_confirmed"] = True

                if text:
                    session = merge_order_message(sender_id, text)

                if incoming_image_url:
                    extracted_from_image = extract_order_fields_from_image(
                        incoming_image_url,
                        text,
                    )
                    session = merge_extracted_order_data(
                        session,
                        extracted_from_image,
                    )

                explicit_qty = extract_explicit_quantity(text)
                if explicit_qty is not None:
                    target_code = session.get("last_product_code")
                    coded = find_codes_and_quantities(text)

                    if coded:
                        for item_code, qty in coded.items():
                            if item_code in PRODUCTS:
                                session["items"][item_code] = qty
                    elif target_code in PRODUCTS:
                        session["items"][target_code] = explicit_qty

                    session["quantity_confirmed"] = True

                missing = order_missing_fields(session)

                if missing:
                    send_facebook_text(
                        sender_id,
                        order_prompt_for_missing(missing),
                    )
                else:
                    telegram_text = build_telegram_order(session)

                    if send_telegram_message(telegram_text):
                        send_facebook_text(
                            sender_id,
                            buyer_order_confirmation(session),
                        )
                        send_facebook_text(
                            sender_id,
                            post_order_delivery_time_message(),
                        )
                        mark_order_completed(sender_id)
                        ORDER_SESSIONS[sender_id] = new_order_session()
                    else:
                        handoff_to_admin(sender_id)

                continue

            # Product question only: send product image + one text reply.
            if product:
                send_product_response(sender_id, code, product)
                continue

            # ---------------------------------
            # SIMPLE GREETING ONLY
            # ---------------------------------
            greeting = simple_greeting(text)

            if greeting:
                if unresolved_product_should_handoff(session):
                    handoff_to_admin(sender_id)
                else:
                    send_facebook_text(sender_id, greeting)
                continue

            # ---------------------------------
            # Nonshopping/unknown text: hand over once, then remain silent.
            handoff_to_admin(sender_id)

    return "EVENT_RECEIVED", 200


# Messenger vouchers are opt-in and use independently authenticated page routes.
VOUCHER_PAGES = {
    "d4a3f384-4153-44f7-b010-08eacd86d1da": ("SP", "Snow Phyu Online Shopping"),
    "ed5c5a8c-052b-5ce6-80bc-4d0e77df0bfe": ("MH", "Mingalar Happy Shopping"),
}


def voucher_mode():
    return os.environ.get("VOUCHER_MODE", "off").strip().lower()


def voucher_database_configured():
    return (
        os.environ.get("VOUCHER_SUPABASE_URL", "").startswith("https://")
        and bool(os.environ.get("VOUCHER_SUPABASE_SERVICE_ROLE_KEY"))
    )


def verified_voucher_subscriber(contact_id, page_name):
    if voucher_mode() not in ("test", "live") or not voucher_database_configured():
        return None
    page = "MH" if is_mingalar_page(page_name) else "SP"
    expected = os.environ.get(f"VOUCHER_{page}_WEBHOOK_KEY", "")
    other_page = "SP" if page == "MH" else "MH"
    provided = getattr(g, "voucher_key", "")
    if (len(expected) < 32 or expected == os.environ.get(f"VOUCHER_{other_page}_WEBHOOK_KEY")
            or not provided.isascii() or not expected.isascii()
            or not hmac.compare_digest(provided, expected)):
        return None
    if not re.fullmatch(r"[1-9][0-9]{0,18}", contact_id):
        return None
    subscriber = int(contact_id)
    if subscriber >= 2**63:
        return None
    if voucher_mode() == "test" and str(subscriber) != os.environ.get(f"VOUCHER_{page}_TEST_CONTACT_ID"):
        return None
    return subscriber


def voucher_database(method, path, payload, prefer=None):
    base = os.environ["VOUCHER_SUPABASE_URL"].rstrip("/")
    key = os.environ["VOUCHER_SUPABASE_SERVICE_ROLE_KEY"]
    headers = {"apikey": key, "Authorization": f"Bearer {key}"}
    if prefer:
        headers["Prefer"] = prefer
    response = requests.request(method, f"{base}/rest/v1/{path}", json=payload, headers=headers,
                                timeout=10, allow_redirects=False)
    if not 200 <= response.status_code < 300:
        raise requests.HTTPError(f"Voucher database HTTP {response.status_code}")
    return response.json() if response.content else None


def register_voucher_route(chat_id, message_id, message, subscriber):
    voucher_database("POST", "messenger_voucher_routes?on_conflict=chat_id,message_id", {
        "chat_id": int(chat_id), "message_id": int(message_id), "subscriber_id": subscriber,
        "text_hash": hashlib.md5(message.encode("utf-8")).hexdigest(),
    }, prefer="resolution=ignore-duplicates,return=minimal")


