_VOUCHER_INK = "#111827"
_VOUCHER_MUTED = "#475569"
_VOUCHER_LEFT, _VOUCHER_RIGHT = 85, 915
_VOUCHER_DASHBOARD_LOGOS = {"SP": "snow-phyu.jpg", "MH": "mingalar-happy.jpg"}
_VOUCHER_PHONES = {"SP": "09671962554", "MH": "09686082833"}


@lru_cache(maxsize=32)
def _voucher_font(size, bold, myanmar):
    from PIL import ImageFont

    family = "NotoSansMyanmar" if myanmar else "NotoSans"
    weight = "Bold" if bold else "Regular"
    return ImageFont.truetype(io.BytesIO(base64.b64decode(_VOUCHER_ASSETS_BASE64[f"{family}-{weight}.ttf"])), size,
                              layout_engine=ImageFont.Layout.RAQM)


def render_voucher(page, shop_name, body):
    from PIL import Image, ImageDraw, features

    if not features.check_feature("raqm"):
        raise ValueError("Myanmar voucher rendering requires Pillow RAQM")
    settings = body.get("shop") or {}
    address = body.get("address")
    phones = body.get("phones") or []
    if not address or not phones or not body.get("items"):
        raise ValueError("Voucher is missing customer details or items")

    image = Image.new("RGB", (1000, 5000), "white")
    draw = ImageDraw.Draw(image)
    y = 65

    def runs(value, size, bold):
        parts = re.findall(r"[\u1000-\u109f\uaa60-\uaa7f\ua9e0-\ua9ff]+|[^\u1000-\u109f\uaa60-\uaa7f\ua9e0-\ua9ff]+", value)
        return [(part, _voucher_font(size, bold, bool(re.match(r"[\u1000-\u109f\uaa60-\uaa7f\ua9e0-\ua9ff]", part)))) for part in parts]

    def measure(value, size, bold):
        return sum(draw.textlength(part, font=f) for part, f in runs(value, size, bold))

    def line(value, size=24, bold=False, center=False, color=_VOUCHER_INK):
        nonlocal y
        words = str(value).split()
        row = ""
        rows = []
        for word in words:
            candidate = f"{row} {word}".strip()
            if row and measure(candidate, size, bold) > _VOUCHER_RIGHT - _VOUCHER_LEFT:
                rows.append(row)
                row = word
            else:
                row = candidate
        rows.append(row)
        for row in rows:
            fitting_size = size
            while measure(row, fitting_size, bold) > _VOUCHER_RIGHT - _VOUCHER_LEFT and fitting_size > 14:
                fitting_size -= 1
            if measure(row, fitting_size, bold) > _VOUCHER_RIGHT - _VOUCHER_LEFT:
                raise ValueError("Voucher field exceeds image width")
            x = (1000 - measure(row, fitting_size, bold)) / 2 if center else _VOUCHER_LEFT
            for part, f in runs(row, fitting_size, bold):
                draw.text((x, y + size), part, font=f, fill=color, anchor="ls")
                x += draw.textlength(part, font=f)
            y += int(size * 1.64)

    def separator(dashed=True):
        nonlocal y
        if dashed:
            for x in range(_VOUCHER_LEFT, _VOUCHER_RIGHT, 13):
                draw.line((x, y, min(x + 6, _VOUCHER_RIGHT), y), fill="#64748b", width=1)
        else:
            draw.line((_VOUCHER_LEFT, y, _VOUCHER_RIGHT, y), fill=_VOUCHER_INK, width=3)
        y += 13

    def amount_box(value):
        nonlocal y
        amount = format(Decimal(str(value)).normalize(), ",f")
        draw.rounded_rectangle((360, y, 640, y + 64), radius=6, outline=_VOUCHER_INK, width=3)
        y += 11
        line(f"{amount} Ks", size=26, bold=True, center=True)
        y += 26

    custom_logo = re.fullmatch(r"data:image/(?:png|jpeg|webp);base64,([A-Za-z0-9+/=]+)", settings.get("logo") or "")
    logo_source = io.BytesIO(base64.b64decode(_VOUCHER_ASSETS_BASE64[_VOUCHER_DASHBOARD_LOGOS[page]]))
    if custom_logo and len(custom_logo[1]) <= 2_000_000:
        logo_source = io.BytesIO(base64.b64decode(custom_logo[1], validate=True))
    with Image.open(logo_source) as logo:
        logo.thumbnail((130, 130))
        logo = logo.convert("RGBA")
        image.paste(logo, ((1000 - logo.width) // 2, y), logo)
        y += logo.height + 15
    line(settings.get("name") or shop_name, size=37, bold=True, center=True)
    line(f"{settings.get('address', 'ရန်ကုန်')} — {settings.get('phone', _VOUCHER_PHONES[page])}",
         size=23, bold=True, center=True)
    y += 12
    separator()

    order_no = str(body["order_no"]).translate(str.maketrans("၀၁၂၃၄၅၆၇၈၉", "0123456789"))
    digits = re.sub(r"[^0-9]", "", order_no)
    local_date = datetime.fromisoformat(body["created_at"].replace("Z", "+00:00")).astimezone(
        timezone(timedelta(hours=6, minutes=30)))
    line(f"Order No. — {digits[-6:].zfill(6) if digits else order_no}")
    line(f"Date — {local_date:%d/%m/%Y, %H:%M}")
    line(f"Name — {body.get('name') or '—'}")
    line(f"Address — {address}")
    line(f"Phone — {' / '.join(phones)}")
    y += 10
    amount_box(body["cod"])
    separator()
    for item in body["items"]:
        line(f"{item['code']} — {item['name']}", size=23, bold=True)
        line(f"Quantity: {item['qty']}", size=20, color=_VOUCHER_MUTED)
        y += 5
    separator(False)
    line("Total COD", size=23, bold=True, center=True)
    amount_box(body["cod"])
    line(settings.get("footer", "ဝယ်ယူအားပေးမှုအတွက် ကျေးဇူးတင်ပါသည်"), size=22, center=True, color=_VOUCHER_MUTED)
    if y > 4870:
        raise ValueError("Voucher exceeds maximum image height")
    buffer = io.BytesIO()
    image.crop((0, 0, 1000, max(1414, y + 65))).save(buffer, "PNG", optimize=True)
    return buffer.getvalue()


def voucher_image_signature(order_id, expires):
    key = os.environ["VOUCHER_SUPABASE_SERVICE_ROLE_KEY"].encode("utf-8")
    return hmac.new(key, f"messenger-voucher-image:{order_id}:{expires}".encode(), hashlib.sha256).hexdigest()


@app.route("/messenger-voucher/<uuid:order_id>/<int:expires>/<signature>.png", methods=["GET"])
def messenger_voucher_image(order_id, expires, signature):
    now = int(time.time())
    if (not voucher_database_configured() or expires <= now or expires > now + 600
            or not re.fullmatch(r"[0-9a-f]{64}", signature)
            or not hmac.compare_digest(signature, voucher_image_signature(order_id, expires))):
        return Response(status=404)
    try:
        rows = voucher_database("GET", "messenger_voucher_outbox"
            f"?order_id=eq.{order_id}&status=in.(sending,sent)&select=business_id,body", None)
        if not rows or not (rows[0].get("body") or {}).get("voucher_image"):
            return Response(status=404)
        row = rows[0]
        page, shop = VOUCHER_PAGES[row["business_id"]]
        png = render_voucher(page, shop, row["body"])
    except (requests.RequestException, ImportError, OSError, KeyError, TypeError, ValueError):
        return Response(status=503)
    return Response(png, mimetype="image/png", headers={
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
        "Referrer-Policy": "no-referrer",
    })


def dispatch_messenger_voucher(job):
    page, shop = VOUCHER_PAGES[job["business_id"]]
    subscriber = job["subscriber_id"]
    if voucher_mode() == "test" and str(subscriber) != os.environ.get(f"VOUCHER_{page}_TEST_CONTACT_ID"):
        return "review"
    token = os.environ.get(f"VOUCHER_{page}_MANYCHAT_API_KEY", "")
    other_page = "SP" if page == "MH" else "MH"
    if not token or token == os.environ.get(f"VOUCHER_{other_page}_MANYCHAT_API_KEY"):
        return "review"
    origin = os.environ.get("RENDER_EXTERNAL_URL", "").rstrip("/")
    if not re.fullmatch(r"https://[a-zA-Z0-9.-]+", origin) or not (job.get("body") or {}).get("voucher_image"):
        return "review"
    render_voucher(page, shop, job["body"])  # Validate rendering before asking ManyChat to fetch it.
    order_id = job["order_id"]
    expires = int(time.time()) + 600
    signature = voucher_image_signature(order_id, expires)
    image_url = f"{origin}/messenger-voucher/{order_id}/{expires}/{signature}.png"
    response = requests.post("https://api.manychat.com/fb/sending/sendContent",
        headers={"Authorization": f"Bearer {token}"},
        json={"subscriber_id": subscriber, "data": {"version": "v2", "content": {
            "messages": [{"type": "image", "url": image_url}],
        }}},
        timeout=15, allow_redirects=False)
    if response.status_code >= 500:
        return "review"  # Provider acceptance may be uncertain. Never retry automatically.
    if not 200 <= response.status_code < 300:
        return "failed"
    return "sent" if response.json().get("status") == "success" else "review"


def run_voucher_worker():
    print("MESSENGER VOUCHER WORKER", voucher_mode(), flush=True)
    while True:
        try:
            job = voucher_database("POST", "rpc/claim_messenger_voucher", {})
            if job:
                try:
                    status = dispatch_messenger_voucher(job)
                except (requests.RequestException, ImportError, OSError, KeyError, ValueError, TypeError):
                    status = "review"
                voucher_database("PATCH",
                    f"messenger_voucher_outbox?order_id=eq.{job['order_id']}&status=eq.sending",
                    {"status": status, "updated_at": datetime.now(timezone.utc).isoformat()})
                print("VOUCHER", job["order_id"], status, flush=True)
                continue
        except (requests.RequestException, KeyError, ValueError, TypeError) as error:
            print("VOUCHER WORKER", type(error).__name__, flush=True)
        time.sleep(5)


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 10000))

    if voucher_mode() in ("test", "live"):
        if not voucher_database_configured():
            print("VOUCHER WORKER DISABLED: Supabase configuration missing", flush=True)
        else:
            threading.Thread(target=run_voucher_worker, daemon=True).start()

    app.run(
        host="0.0.0.0",
        port=port,
    )
